declare @name nvarchar(4000), @name_reason nvarchar(4000)
select @name = rtrim(isnull(case when @@language = 'V' then ten_kh else ten_kh2 end, '')) from dmkh where ma_kh = @ma_kh
select 'this._itemName = ''' + replace(replace(isnull(@name, ''), '\', '\\'), '''', '\''') + ''';this._queryFilterString = ''' + replace(replace(@@queryString, '\', '\\'), '''', '\''') + ''';init$GridQuery$(this);' as message
return




